const lessons=[{"sentences":[{"speaker":"A","text":"Good morning and welcome to the community arts centre booking office.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.398166666666667},{"speaker":"B","text":"Hello I would like to ask about the weekend music workshop.","position":2,"audioStartSeconds":4.598166666666667,"audioEndSeconds":8.725333333333333},{"speaker":"A","text":"Certainly we organise guitar and piano sessions every Saturday morning.","position":3,"audioStartSeconds":8.925333333333333,"audioEndSeconds":13.75975},{"speaker":"B","text":"I am interested in the guitar class which takes place in room fifteen.","position":4,"audioStartSeconds":13.95975,"audioEndSeconds":18.432166666666667},{"speaker":"A","text":"Actually we changed the venue to room twelve because it is much larger.","position":5,"audioStartSeconds":18.632166666666667,"audioEndSeconds":22.987833333333334},{"speaker":"B","text":"That is good to know since many students joined this month.","position":6,"audioStartSeconds":23.187833333333334,"audioEndSeconds":27.040916666666668},{"speaker":"A","text":"Yes the fee is normally fifty pounds but students pay forty pounds.","position":7,"audioStartSeconds":27.240916666666667,"audioEndSeconds":31.854333333333333},{"speaker":"B","text":"Do I need to bring my own acoustic guitar for the lesson?","position":8,"audioStartSeconds":32.05433333333333,"audioEndSeconds":35.623916666666666},{"speaker":"A","text":"You must bring your own instrument although we supply extra music stands.","position":9,"audioStartSeconds":35.82391666666667,"audioEndSeconds":40.47595833333333},{"speaker":"B","text":"Should I also bring a notebook to write down some chords?","position":10,"audioStartSeconds":40.675958333333334,"audioEndSeconds":44.438875},{"speaker":"A","text":"A notebook is helpful and please bring a pencil for your sheet music.","position":11,"audioStartSeconds":44.638875,"audioEndSeconds":48.94920833333333},{"speaker":"B","text":"Thank you for all your helpful guidance today.","position":12,"audioStartSeconds":49.149208333333334,"audioEndSeconds":52.52033333333333}],"questions":[{"prompt":"Workshop instrument: ______","answer":"guitar","evidenceSentence":4,"evidence":"guitar","explanation":"Người nghe quan tâm đến lớp học đàn guitar."},{"prompt":"Current room number: ______","answer":"room twelve","evidenceSentence":5,"evidence":"room twelve","explanation":"Địa điểm đã được đổi sang phòng số mười hai."},{"prompt":"Student fee amount: ______ pounds","answer":"forty","evidenceSentence":7,"evidence":"forty","explanation":"Học sinh chỉ phải trả bốn mươi bảng."},{"prompt":"Required instrument: ______","answer":"acoustic guitar","evidenceSentence":8,"evidence":"acoustic guitar","explanation":"Người tham gia cần mang theo đàn guitar thùng của riêng mình."},{"prompt":"Provided items: ______","answer":"music stands","evidenceSentence":9,"evidence":"music stands","explanation":"Trung tâm cung cấp sẵn các giá để bản nhạc."},{"prompt":"Writing tool needed: ______","answer":"pencil","evidenceSentence":11,"evidence":"pencil","explanation":"Người tổ chức dặn mang theo một cây bút chì cho bản nhạc."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
